using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using Racer;
public static class InspectReportBend {public static string Main(){Physics.SyncTransforms();var rows=new List<string>();for(float x=1346;x<1355;x+=.25f){var hits=Physics.RaycastAll(new Vector3(x,105,-273.5f),Vector3.down,15,~0,QueryTriggerInteraction.Ignore).OrderByDescending(h=>h.point.y);rows.Add(x+": "+string.Join("; ",hits.Select(h=>h.collider.name+" y="+h.point.y+" normal="+h.normal)));}foreach(var c in UnityEngine.Object.FindObjectsByType<Collider>().Where(c=>c.bounds.Intersects(new Bounds(new Vector3(1350,100,-274),new Vector3(10,8,10)))))rows.Add("NEAR "+c.name+" "+c.bounds+" enabled="+c.enabled);File.WriteAllLines("Docs/ReportCleanup/BUG-015-contact-inspection.txt",rows);return string.Join("\n",rows);}}
